import{_ as e,o as d,c as a,a2 as l}from"./chunks/framework.7R1OEGYz.js";const s=JSON.parse('{"title":"올바름 인력관리시스템 배포 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"deployment-guide.md","filePath":"deployment-guide.md"}'),i={name:"deployment-guide.md"};function o(r,t,c,_,n,u){return d(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="올바름-인력관리시스템-배포-가이드" tabindex="-1">올바름 인력관리시스템 배포 가이드 <a class="header-anchor" href="#올바름-인력관리시스템-배포-가이드" aria-label="Permalink to &quot;올바름 인력관리시스템 배포 가이드&quot;">​</a></h1><h2 id="_1-배포-구성" tabindex="-1">1. 배포 구성 <a class="header-anchor" href="#_1-배포-구성" aria-label="Permalink to &quot;1. 배포 구성&quot;">​</a></h2><ul><li>애플리케이션: Vercel deployment server</li><li>데이터베이스·인증·저장소: Supabase</li><li>정기 작업: Supabase Cron 및 Edge Function</li><li>외부 연동: Kakao 지도, 도로명주소, Naver mail, Web Push</li></ul><h2 id="_2-사전-준비" tabindex="-1">2. 사전 준비 <a class="header-anchor" href="#_2-사전-준비" aria-label="Permalink to &quot;2. 사전 준비&quot;">​</a></h2><ul><li>GitHub 저장소와 Vercel 프로젝트를 연결한다.</li><li>운영 Supabase 프로젝트를 생성하고 연결 정보를 확보한다.</li><li>외부 서비스 운영 키와 발신 계정을 준비한다.</li><li>운영 도메인과 HTTPS 적용 여부를 확인한다.</li></ul><h2 id="_3-환경변수" tabindex="-1">3. 환경변수 <a class="header-anchor" href="#_3-환경변수" aria-label="Permalink to &quot;3. 환경변수&quot;">​</a></h2><table tabindex="0"><thead><tr><th>변수</th><th>용도</th><th>노출 범위</th></tr></thead><tbody><tr><td><code>NEXT_PUBLIC_SUPABASE_URL</code></td><td>Supabase 프로젝트 URL</td><td>클라이언트 허용</td></tr><tr><td><code>NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY</code></td><td>Supabase 공개키</td><td>클라이언트 허용</td></tr><tr><td><code>SUPABASE_SECRET_KEY</code> 또는 <code>SUPABASE_SERVICE_ROLE_KEY</code></td><td>서버 관리 작업</td><td>서버 전용</td></tr><tr><td><code>kakao_map_key</code></td><td>Kakao 지도·좌표 변환</td><td>서버 전용</td></tr><tr><td><code>juso_key</code></td><td>도로명주소 검색</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_USER</code></td><td>Naver SMTP 계정</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_PASSWORD</code></td><td>Naver SMTP 비밀번호</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_PORT</code></td><td>SMTP 포트</td><td>서버 전용</td></tr><tr><td><code>NAVER_SMTP_FROM</code></td><td>발신 주소</td><td>서버 전용</td></tr><tr><td><code>NEXT_PUBLIC_VAPID_PUBLIC_KEY</code></td><td>Web Push 공개키</td><td>클라이언트 허용</td></tr><tr><td><code>VAPID_PRIVATE_KEY</code></td><td>Web Push 개인키</td><td>서버 전용</td></tr><tr><td><code>EDUCATION_REMINDER_CRON_SECRET</code></td><td>교육 알림 예약 호출 검증</td><td>서버 전용</td></tr></tbody></table><h2 id="_4-배포-절차" tabindex="-1">4. 배포 절차 <a class="header-anchor" href="#_4-배포-절차" aria-label="Permalink to &quot;4. 배포 절차&quot;">​</a></h2><ol><li>대상 커밋과 변경 내역을 확인한다.</li><li><code>npm ci</code>, <code>npm run lint</code>, <code>npm test</code>, <code>npm run build</code>를 통과시킨다.</li><li>Supabase 마이그레이션을 스테이징에서 먼저 적용한다.</li><li>운영 DB를 백업하고 마이그레이션을 적용한다.</li><li>Vercel 환경변수를 설정하고 대상 커밋을 배포한다.</li><li>필요한 Supabase Edge Function과 Vault 비밀값을 배포한다.</li><li>도메인, 인증 콜백 URL, PWA 파일과 Service Worker를 확인한다.</li><li>배포 후 점검을 완료하고 배포 기록을 남긴다.</li></ol><h2 id="_5-배포-후-점검" tabindex="-1">5. 배포 후 점검 <a class="header-anchor" href="#_5-배포-후-점검" aria-label="Permalink to &quot;5. 배포 후 점검&quot;">​</a></h2><ul><li>회사소개 홈페이지와 관리자·근무자 진입 화면 응답</li><li>관리자 로그인과 보호 화면 접근</li><li>직원·근무지·배정 조회</li><li>테스트 근무자의 로그인과 프로필 조회</li><li>지도·주소 검색, Naver mail, 푸시 알림 연결</li><li>정적 이미지, 아이콘, 폰트, PWA 설치 정보</li><li>서버 로그의 반복 오류와 5xx 응답 여부</li></ul><h2 id="_6-롤백" tabindex="-1">6. 롤백 <a class="header-anchor" href="#_6-롤백" aria-label="Permalink to &quot;6. 롤백&quot;">​</a></h2><ul><li>애플리케이션 문제는 Vercel의 직전 정상 배포를 재배포한다.</li><li>DB 변경은 사전에 검증한 역마이그레이션 또는 백업 복구 절차를 사용한다.</li><li>데이터가 변경된 후에는 애플리케이션만 먼저 되돌리지 말고 스키마 호환성을 확인한다.</li><li>장애 원인, 영향 범위, 롤백 시각과 결과를 기록한다.</li></ul><h2 id="_7-보안-주의사항" tabindex="-1">7. 보안 주의사항 <a class="header-anchor" href="#_7-보안-주의사항" aria-label="Permalink to &quot;7. 보안 주의사항&quot;">​</a></h2><ul><li><code>.env</code> 파일과 실제 키를 Git에 커밋하지 않는다.</li><li>Preview와 Production 환경변수를 구분한다.</li><li>퇴사자·담당자 변경 시 서비스 계정과 키를 교체한다.</li><li>비밀값이 노출되면 즉시 폐기·재발급하고 관련 로그를 점검한다.</li></ul>',15)])])}const P=e(i,[["render",o]]);export{s as __pageData,P as default};
